/* Output and update for atomic system: '<S876>/ComputeCurvatureBasedControlPoint' */
void LongSafe_SWC_ComputeCurvatureBasedControlPoint(real32_T
  rtu_PositionLongitudinal, real32_T rtu_PositionLateral, real32_T rtu_V,
  real32_T rtu_A, real32_T rtu_HeadingAngle, real32_T rtu_Curvature, real32_T
  rtu_CurvatureRate, boolean_T rtu_StopsWithinSegment, real32_T
  rtu_LongitudinalStoppingDistance, real32_T rtu_LateralStoppingDistance,
  real32_T *rty_P3Longitudinal, real32_T *rty_P3Lateral)
{
  real32_T r2;
  boolean_T guard1 = false;
  guard1 = false;
  if (fabsf(rtu_Curvature) > 1.0E-5F) {
    r2 = rtu_Curvature + rtu_CurvatureRate;
    if (fabsf(r2) > 1.0E-5F) {
      real32_T angleOfArc1;
      real32_T angleOfArc2;
      real32_T distance;
      real32_T r1;
      real32_T tmp;
      distance = rtu_A / 2.0F + rtu_V;
      r1 = 1.0F / rtu_Curvature;
      r2 = 1.0F / r2;
      angleOfArc1 = distance / r1;
      angleOfArc2 = distance / r2;
      distance = r1 * sinf(angleOfArc1);
      r1 += -r1 * cosf(angleOfArc1);
      angleOfArc1 = r2 * sinf(angleOfArc2);
      angleOfArc2 = -r2 * cosf(angleOfArc2) + r2;
      r2 = cosf(rtu_HeadingAngle);
      tmp = sinf(rtu_HeadingAngle);
      *rty_P3Longitudinal = ((distance * r2 - r1 * tmp) * 0.7F +
        rtu_PositionLongitudinal) + (angleOfArc1 * r2 - angleOfArc2 * tmp) *
        0.3F;
      *rty_P3Lateral = ((distance * tmp + r1 * r2) * 0.7F + rtu_PositionLateral)
        + (angleOfArc1 * tmp + angleOfArc2 * r2) * 0.3F;
    } else {
      guard1 = true;
    }
  } else {
    guard1 = true;
  }

  if (guard1) {
    r2 = rtu_A / 2.0F + rtu_V;
    *rty_P3Longitudinal = r2 * cosf(rtu_HeadingAngle) + rtu_PositionLongitudinal;
    *rty_P3Lateral = r2 * sinf(rtu_HeadingAngle) + rtu_PositionLateral;
  }

  if (rtu_StopsWithinSegment) {
    *rty_P3Longitudinal = rtu_PositionLongitudinal +
      rtu_LongitudinalStoppingDistance;
    *rty_P3Lateral = rtu_PositionLateral + rtu_LateralStoppingDistance;
  }
}

