  /* Sum: '<S2939>/Add9' */
  rtb_NewPosnLgt_a = rtb_NewPosnLat_k + rtu_Obj->Estimn.AgDir;

  /* SignalConversion: '<S2938>/Signal Conversion' */
  *rty_PosnObjAtTTR_ev = rtb_NewPosnLgt_a;

