  *rty_PosnObjAtTTR_l = rtb_ResultingALat;

  /* SignalConversion: '<S3103>/Signal Conversion' */
  *rty_AObjIfManoeuvering_f = rtu_Obj->Estimn.Crvt;

  /* SignalConversion: '<S3104>/Signal Conversion' */
  *rty_AObjIfManoeuvering_e = rtb_Quotient_mmx;

  /* SignalConversion: '<S3105>/Signal Conversion' */
  *rty_AObjIfManoeuvering_h = rtb_ResultingALgt;

  /* Trigonometry: '<S3052>/Trigonometric Function' */
  rtb_ResultingALat = rt_atan2f_snf(rtb_ResultingALat,
    rtb_TrigonometricFunction_j);

  /* SignalConversion: '<S3106>/Signal Conversion' */
  *rty_PosnObjAtTTR_k = rtb_ResultingALat;

  /* Switch: '<S3052>/Switch3' incorporates:
   *  Constant: '<S3099>/Constant'
   *  Constant: '<S3100>/Constant'
   *  Product: '<S3052>/Product'
   *  Product: '<S3099>/Product1'
   *  Product: '<S3099>/Product4'
   *  Product: '<S3099>/Product5'
   *  Product: '<S3100>/Product1'
   *  Product: '<S3100>/Product4'
   *  Product: '<S3100>/Product5'
   *  Product: '<S3107>/Product2'
   *  Product: '<S3109>/Product2'
   *  Sum: '<S3099>/Sum6'
   *  Sum: '<S3100>/Sum6'
   *  Sum: '<S3107>/Add2'
   *  Sum: '<S3109>/Add2'
   *  Switch: '<S3052>/Switch4'
   *  Trigonometry: '<S3052>/Trigonometric Function2'
   *  Trigonometry: '<S3052>/Trigonometric Function3'
   */
  if (rtb_TestOk_ml) {
    *rty_PosnObjAtTTR_gc = (rtb_VPred_e_tmp * rtb_Quotient_mmx *
      rtCP_Constant_Value_jn + (rtb_VPred_e_tmp_0 + rtb_TestOk_gf_0)) +
      rtb_PosnPred_o_tmp * sinf(rtb_ResultingALat);
    *rty_PosnObjAtTTR_cv = (rtu_TTR * rtu_TTR * rtb_ResultingALgt *
      rtCP_Constant_Value_h4h + (rtu_Obj->Estimn.VLgt * rtu_TTR + rtb_TestOk_gf))
      + rtb_PosnPred_o_tmp * cosf(rtb_ResultingALat);
  } else {
    *rty_PosnObjAtTTR_gc = rtb_VPred_e_tmp * rtb_Quotient_mmx *
      rtCP_Constant_Value_jn + (rtb_VPred_e_tmp_0 + rtb_TestOk_gf_0);
    *rty_PosnObjAtTTR_cv = rtb_VPred_e_tmp * rtb_ResultingALgt *
      rtCP_Constant_Value_h4h + (rtu_Obj->Estimn.VLgt * rtu_TTR + rtb_TestOk_gf);
  }

  /* End of Switch: '<S3052>/Switch3' */

  /* Switch: '<S3113>/Switch_2' incorporates:
   *  Constant: '<S2929>/False'
   *  Gain: '<S3113>/Gain_1'
   *  Gain: '<S3113>/Gain_2'
   *  Switch: '<S3113>/Switch_1'
   */
  if (rtCP_False_Value_o) {
    rtb_PosnPred_is *= rtCP_Gain_1_Gain_k;
  } else {
    rtb_PositionChangeFromVelocity_n_tmp *= rtCP_Gain_2_Gain_l;
  }

  /* End of Switch: '<S3113>/Switch_2' */

  /* Sum: '<S3113>/Add' */
  rtb_PosnPred_is += rtu_Obj->Estimn.ALgt;

  /* Sum: '<S3113>/Add1' */
  rtb_ResultingALat = rtu_Obj->Estimn.ALat +
    rtb_PositionChangeFromVelocity_n_tmp;

  /* Sum: '<S3115>/Sum3' incorporates:
   *  Product: '<S3115>/Product6'
   */
  rtb_ResultingALgt = rtu_TTR * rtb_PosnPred_is + rtu_Obj->Estimn.VLgt;

  /* RelationalOperator: '<S3053>/Relational Operator' incorporates:
   *  Constant: '<S3114>/Constant'
   */
  rtb_TestOk_ml = (rtu_Obj->Info.MtnPat == rtCP_Constant_Value_ce);

  /* Switch: '<S3053>/Switch1' incorporates:
   *  Product: '<S3126>/Product2'
   *  Sum: '<S3126>/Add2'
   */
  if (rtb_TestOk_ml) {
    rtb_TestOk_gf = rtu_Obj->Estimn.PosnLgt - rtb_PosnPred_o_tmp *
      rtu_CosHeading;
  } else {
    rtb_TestOk_gf = rtu_Obj->Estimn.PosnLgt;
  }

  /* End of Switch: '<S3053>/Switch1' */

  /* Sum: '<S3116>/Sum3' incorporates:
   *  Product: '<S3116>/Product6'
   */
  rtb_TrigonometricFunction_j = rtu_TTR * rtb_ResultingALat +
    rtu_Obj->Estimn.VLat;

  /* Switch: '<S3053>/Switch2' incorporates:
   *  Product: '<S3124>/Product2'
   *  Sum: '<S3124>/Add2'
   */
  if (rtb_TestOk_ml) {
    rtb_TestOk_gf_0 = rtu_Obj->Estimn.PosnLat - rtb_PosnPred_o_tmp *
      rtu_SinHeading;
  } else {
    rtb_TestOk_gf_0 = rtu_Obj->Estimn.PosnLat;
  }

  /* End of Switch: '<S3053>/Switch2' */

  /* SignalConversion: '<S3117>/Signal Conversion' */
  *rty_PosnObjAtTTR_n = rtb_ResultingALgt;

  /* SignalConversion: '<S3118>/Signal Conversion' */
  *rty_PosnObjAtTTR_a3 = rtb_TrigonometricFunction_j;

  /* SignalConversion: '<S3119>/Signal Conversion' incorporates:
   *  SignalConversion: '<S3103>/Signal Conversion'
   */
  *rty_AObjIfManoeuvering_cy = rtu_Obj->Estimn.Crvt;

  /* SignalConversion: '<S3120>/Signal Conversion' */
  *rty_AObjIfManoeuvering_c = rtb_ResultingALat;

  /* SignalConversion: '<S3121>/Signal Conversion' */
  *rty_AObjIfManoeuvering_n = rtb_PosnPred_is;

  /* Trigonometry: '<S3053>/Trigonometric Function' */
  rtb_TrigonometricFunction_j = rt_atan2f_snf(rtb_TrigonometricFunction_j,
    rtb_ResultingALgt);

  /* SignalConversion: '<S3122>/Signal Conversion' */
  *rty_PosnObjAtTTR_f = rtb_TrigonometricFunction_j;

  /* Switch: '<S3053>/Switch3' incorporates:
   *  Constant: '<S3115>/Constant'
   *  Constant: '<S3116>/Constant'
   *  Product: '<S3115>/Product1'
   *  Product: '<S3115>/Product4'
   *  Product: '<S3115>/Product5'
   *  Product: '<S3116>/Product5'
   *  Product: '<S3123>/Product2'
   *  Product: '<S3125>/Product2'
   *  Sum: '<S3115>/Sum6'
   *  Sum: '<S3116>/Sum6'
   *  Sum: '<S3123>/Add2'
   *  Sum: '<S3125>/Add2'
   *  Switch: '<S3053>/Switch4'
   *  Trigonometry: '<S3053>/Trigonometric Function2'
   *  Trigonometry: '<S3053>/Trigonometric Function3'
   */
  if (rtb_TestOk_ml) {
    *rty_PosnObjAtTTR_mi = (rtb_VPred_e_tmp * rtb_ResultingALat *
      rtCP_Constant_Value_ekk + (rtb_VPred_e_tmp_0 + rtb_TestOk_gf_0)) +
      rtb_PosnPred_o_tmp * sinf(rtb_TrigonometricFunction_j);
    *rty_PosnObjAtTTR_jj = (rtu_TTR * rtu_TTR * rtb_PosnPred_is *
      rtCP_Constant_Value_nl + (rtu_Obj->Estimn.VLgt * rtu_TTR + rtb_TestOk_gf))
      + rtb_PosnPred_o_tmp * cosf(rtb_TrigonometricFunction_j);
  } else {
    *rty_PosnObjAtTTR_mi = rtb_VPred_e_tmp * rtb_ResultingALat *
      rtCP_Constant_Value_ekk + (rtb_VPred_e_tmp_0 + rtb_TestOk_gf_0);
    *rty_PosnObjAtTTR_jj = rtb_VPred_e_tmp * rtb_PosnPred_is *
      rtCP_Constant_Value_nl + (rtu_Obj->Estimn.VLgt * rtu_TTR + rtb_TestOk_gf);
  }

  /* End of Switch: '<S3053>/Switch3' */

  /* Outputs for Atomic SubSystem: '<S3134>/SafeDivide' */
  /* MATLAB Function: '<S3138>/SafeDivide' */
  if (fabsf(rtu_Obj->Estimn.ALgt) > rtb_Quotient_eh) {
    rtb_Quotient_eh = rtu_Obj->Estimn.VLgt / rtu_Obj->Estimn.ALgt;
  } else if (rtu_Obj->Estimn.VLgt > 0.0F) {
    rtb_Quotient_eh = LongSafe_SWC_DataTypeMax_p0;
  } else if (rtu_Obj->Estimn.VLgt < 0.0F) {
    rtb_Quotient_eh = LongSafe_SWC_DataTypeMin_ar;
  } else {
    rtb_Quotient_eh = 0.0F;
  }

  /* End of Outputs for SubSystem: '<S3134>/SafeDivide' */

  /* Gain: '<S3134>/Gain' */
  rtb_PosnPred_is = rtCP_Gain_Gain_bn * rtb_Quotient_eh;

  /* Switch: '<S3134>/Switch' incorporates:
   *  Constant: '<S3137>/Constant'
   *  MinMax: '<S3134>/MinMax'
   *  RelationalOperator: '<S3137>/Compare'
   */
  if (rtb_PosnPred_is > rtCP_Constant_Value_ltj) {
    rtb_PosnPred_is = fminf(rtu_TTR, rtb_PosnPred_is);
  } else {
    rtb_PosnPred_is = rtu_TTR;
  }

  /* End of Switch: '<S3134>/Switch' */

  /* Sum: '<S3133>/Sum6' incorporates:
   *  Constant: '<S3133>/Constant'
   *  Product: '<S3133>/Product1'
   *  Product: '<S3133>/Product4'
   *  Product: '<S3133>/Product5'
   */
  *rty_PosnObjAtTTR = rtb_PosnPred_is * rtb_PosnPred_is * rtu_Obj->Estimn.ALgt *
    rtCP_Constant_Value_dle + (rtu_Obj->Estimn.VLgt * rtb_PosnPred_is +
    rtu_Obj->Estimn.PosnLgt);

  /* Switch: '<S3129>/Switch' incorporates:
   *  Abs: '<S3135>/Abs'
   *  Constant: '<S3129>/Constant1'
   *  Constant: '<S3135>/LimitSource'
   *  Product: '<S3133>/Product6'
   *  RelationalOperator: '<S3135>/Relational Operator'
   *  Sum: '<S3129>/Add'
   *  Sum: '<S3133>/Sum3'
   *  Switch: '<S3129>/Switch1'
   */
  if (fabsf(rtu_TTR - rtb_PosnPred_is) > rtCP_LimitSource_Value_gp) {
    rtb_PosnPred_is = rtCP_Constant1_Value_o1;
  } else {
    rtb_PosnPred_is = rtb_PosnPred_is * rtu_Obj->Estimn.ALgt +
      rtu_Obj->Estimn.VLgt;
  }

  /* End of Switch: '<S3129>/Switch' */

  /* Outputs for Atomic SubSystem: '<S3141>/SafeDivide' */
  /* MATLAB Function: '<S3145>/SafeDivide' */
  if (fabsf(rtu_Obj->Estimn.ALat) > rtb_Quotient_avu) {
    rtb_Quotient_avu = rtu_Obj->Estimn.VLat / rtu_Obj->Estimn.ALat;
  } else if (rtu_Obj->Estimn.VLat > 0.0F) {
    rtb_Quotient_avu = LongSafe_SWC_DataTypeMax_p0;
  } else if (rtu_Obj->Estimn.VLat < 0.0F) {
    rtb_Quotient_avu = LongSafe_SWC_DataTypeMin_ar;
  } else {
    rtb_Quotient_avu = 0.0F;
  }

  /* End of Outputs for SubSystem: '<S3141>/SafeDivide' */

  /* Gain: '<S3141>/Gain' */
  rtb_ResultingALat = rtCP_Gain_Gain_pg * rtb_Quotient_avu;

  /* Switch: '<S3141>/Switch' incorporates:
   *  Constant: '<S3144>/Constant'
   *  MinMax: '<S3141>/MinMax'
   *  RelationalOperator: '<S3144>/Compare'
   */
  if (rtb_ResultingALat > rtCP_Constant_Value_iy) {
    rtb_ResultingALat = fminf(rtu_TTR, rtb_ResultingALat);
  } else {
    rtb_ResultingALat = rtu_TTR;
  }

  /* End of Switch: '<S3141>/Switch' */

  /* Sum: '<S3140>/Sum6' incorporates:
   *  Constant: '<S3140>/Constant'
   *  Product: '<S3140>/Product1'
   *  Product: '<S3140>/Product4'
   *  Product: '<S3140>/Product5'
   */
  *rty_PosnObjAtTTR_d = rtb_ResultingALat * rtb_ResultingALat *
    rtu_Obj->Estimn.ALat * rtCP_Constant_Value_m0z + (rtu_Obj->Estimn.VLat *
    rtb_ResultingALat + rtu_Obj->Estimn.PosnLat);

  /* Switch: '<S3130>/Switch' incorporates:
   *  Abs: '<S3142>/Abs'
   *  Constant: '<S3130>/Constant1'
   *  Constant: '<S3142>/LimitSource'
   *  Product: '<S3140>/Product6'
   *  RelationalOperator: '<S3142>/Relational Operator'
   *  Sum: '<S3130>/Add'
   *  Sum: '<S3140>/Sum3'
   *  Switch: '<S3130>/Switch1'
   */
  if (fabsf(rtu_TTR - rtb_ResultingALat) > rtCP_LimitSource_Value_i) {
    rtb_ResultingALat = rtCP_Constant1_Value_pf;
  } else {
    rtb_ResultingALat = rtb_ResultingALat * rtu_Obj->Estimn.ALat +
      rtu_Obj->Estimn.VLat;
  }

  /* End of Switch: '<S3130>/Switch' */

  /* SignalConversion: '<S3131>/Signal Conversion' */
  *rty_PosnObjAtTTR_o = rtb_ResultingALat;

  /* SignalConversion: '<S3132>/Signal Conversion' */
  *rty_PosnObjAtTTR_c = rtb_PosnPred_is;

  /* Trigonometry: '<S3054>/Trigonometric Function' */
  *rty_PosnObjAtTTR_g = rt_atan2f_snf(rtb_ResultingALat, rtb_PosnPred_is);
