/*
 * Output and update for atomic system:
 *    '<S3207>/DetermineObjectManoeuver'
 *    '<S4892>/DetermineObjectManoeuver'
 */
void LongSafe_SWC_DetermineObjectManoeuver(boolean_T rtu_InPathDefault,
  boolean_T rtu_OncomingBraking, boolean_T rtu_CanBrake, boolean_T
  rtu_CanSteerLeft, boolean_T rtu_CanSteerRight, real32_T rtu_ABraking, real32_T
  rtu_ATurningLeft, real32_T rtu_ATurningRight, boolean_T *rty_WillBrake,
  boolean_T *rty_WillSteerLeft, boolean_T *rty_WillSteerRight)
{
  boolean_T LeftIsEasiest;
  boolean_T WillBrake;
  WillBrake = false;
  *rty_WillSteerLeft = false;
  *rty_WillSteerRight = false;
  LeftIsEasiest = false;
  if (rtu_OncomingBraking && rtu_InPathDefault) {
    WillBrake = true;
  } else {
    boolean_T CanSteer;
    CanSteer = (rtu_CanSteerLeft || rtu_CanSteerRight);
    if (CanSteer && rtu_CanSteerLeft) {
      LeftIsEasiest = ((!rtu_CanSteerRight) || (fabsf(rtu_ATurningLeft) < fabsf
        (rtu_ATurningRight)));
    }

    if (rtu_CanBrake) {
      if (!CanSteer) {
        WillBrake = true;
      } else if (LeftIsEasiest) {
        WillBrake = ((!rtu_CanSteerLeft) || (fabsf(rtu_ABraking) < fabsf
          (rtu_ATurningLeft)));
        *rty_WillSteerLeft = !WillBrake;
      } else {
        WillBrake = ((!rtu_CanSteerRight) || (fabsf(rtu_ABraking) < fabsf
          (rtu_ATurningRight)));
        *rty_WillSteerRight = !WillBrake;
      }
    } else if (CanSteer) {
      if (LeftIsEasiest) {
        *rty_WillSteerLeft = true;
      } else {
        *rty_WillSteerRight = true;
      }
    }
  }

  *rty_WillBrake = WillBrake;
}

